var sc = root.querySelector('.scs-pin-figure-scroll');
var steps = Array.prototype.slice.call(root.querySelectorAll('.scs-pin-figure-step'));
var layers = Array.prototype.slice.call(root.querySelectorAll('.scs-pin-figure-layer'));
var beam = root.querySelector('.scs-pin-figure-beam');
var num = root.querySelector('.scs-pin-figure-n');
var nm = root.querySelector('.scs-pin-figure-nm');
var names = ['accept', 'buffer', 'transform', 'commit'];
if (!sc || !steps.length) return;
var queued = false, cur = -1;
function paint() {
  if (!root.isConnected) return;
  queued = false;
  var y = sc.scrollTop + sc.clientHeight * 0.34, i = 0, n;
  for (n = 0; n < steps.length; n++) { if (steps[n].offsetTop <= y) i = n; }
  if (sc.scrollTop >= sc.scrollHeight - sc.clientHeight - 2) i = steps.length - 1;
  if (i === cur) return;
  cur = i;
  layers.forEach(function (l, n) { l.classList.toggle('scs-pin-figure-on', n === i); });
  if (beam) beam.style.setProperty('--scs-pfg-k', String(i));
  if (num) num.textContent = '0' + (i + 1);
  if (nm) nm.textContent = names[i];
}
sc.addEventListener('scroll', function () {
  if (!queued) { queued = true; requestAnimationFrame(paint); }
}, { passive: true });
paint();

