var sc = root.querySelector('.scs-cta-bar-scroll');
var bar = root.querySelector('.scs-cta-bar-bar');
var go = root.querySelector('.scs-cta-bar-go');
var st = root.querySelector('.scs-cta-bar-status');
if (!sc || !go) return;
var queued = false, armed = false;
function paint() {
  if (!root.isConnected) return;
  queued = false;
  var max = sc.scrollHeight - sc.clientHeight;
  var p = max > 4 ? sc.scrollTop / max : 1;
  if (p > 1) p = 1;
  root.style.setProperty('--scs-cb-p', p.toFixed(3));
  if (bar) bar.classList.toggle('scs-cta-bar-lift', p < 0.98);
  if (!armed && p >= 0.98) {
    armed = true;
    go.disabled = false;
    go.textContent = 'Activate 12 seats';
    go.classList.add('scs-cta-bar-ready');
    if (st) st.textContent = 'Terms read in full. The plan can be activated now.';
  }
}
