  if (go.disabled) return;
  go.textContent = 'Activated';
  go.classList.add('scs-cta-bar-done');
  go.disabled = true;
  if (st) st.textContent = '12 seats activated · renews 31 Aug 2027 · receipt sent to billing@northwind.co';
});
paint();

